-- Keep only what an audit reads (docs/decisions.md D-029). Generated by scripts/make_prune_migration.py from its keep-list.
-- The sandbox datasets D3 (repayments), D6 (promises), D7 (payments), D8 (bank statements), D9 (bureau) and D13 (channel cost) have no bearing on a
-- collections audit and are removed; D1 and D2 keep only the fields an audit uses (no names, birth dates or e-mail addresses).

DROP VIEW IF EXISTS book.d3_repayment_history;
DROP VIEW IF EXISTS book.d6_ptp_ledger;
DROP VIEW IF EXISTS book.d7_payment_feed;
DROP VIEW IF EXISTS book.d8_bank_statements;
DROP VIEW IF EXISTS book.d9_bureau_snapshot;
DROP VIEW IF EXISTS book.d13_channel_cost;
DROP VIEW IF EXISTS staging.collectors;  -- re-created without the role (db/staging/R__140)
-- D1 and D2 keep only the fields an audit reads (the account and its lender, product and DPD; the borrower's numbers with where each came from, and where they live)
DROP VIEW IF EXISTS book.d1_account_master;
CREATE VIEW book.d1_account_master AS
SELECT id AS account_id, institution_code AS lender_id, customer_id AS borrower_id, account_number, product_code AS product, dpd, delinquency_bucket_code AS bucket, city
FROM cn_core.account;
DROP VIEW IF EXISTS book.d2_borrower_master;
CREATE VIEW book.d2_borrower_master AS
SELECT c.id AS borrower_id,
       COALESCE((SELECT jsonb_agg(jsonb_build_object('number', p.contact_no, 'type', p.contact_type, 'source', p.source, 'captured_date', p.captured_date) ORDER BY p.sequence_no)
                 FROM cn_core.customer_contact_number p WHERE p.customer_id = c.id), '[]'::jsonb) AS phones,
       COALESCE((SELECT jsonb_agg(jsonb_build_object('type', d.address_type, 'city', d.city, 'state', d.state) ORDER BY d.sequence_no)
                 FROM cn_core.customer_address d WHERE d.customer_id = c.id), '[]'::jsonb) AS addresses
FROM cn_core.customer c;
GRANT SELECT ON ALL TABLES IN SCHEMA book TO agent_reader;

